/**
 * Scripts SQL Supabase embebidos para Nube global (generado)
 * Regenerar: node scripts/build-supabase-sql-bundles.mjs
 */
(function (global) {
  'use strict';
  global.CrozzoSupabaseSqlBundles = {
    version: 2,
    generatedAt: "2026-06-01T15:40:00.333Z",
    scripts: [{"key":"editor","file":"docs/SUPABASE-SQL-EDITOR.sql","title":"1. Base del POS (tablas principales)","desc":"Perfiles, productos, ventas, comandas, dispositivos y funciones RLS base. Ejecutar primero.","required":true,"order":1,"sql":"-- =============================================================================\n-- CROZZO POS — PEGAR COMPLETO EN: Supabase → SQL → New query → Run\n-- =============================================================================\n-- 1. Copia TODO este archivo en el SQL Editor y ejecuta (▶).\n-- 2. En el POS: Multi-dispositivo → Cloud ON → URL + anon key → Guardar → F5.\n-- 3. «Subir todo a la nube» en la PC maestra. En otro PC: «Bajar de la nube».\n--\n-- Modo simple: NO hace falta activar Realtime ni Réplicas (opcional).\n-- Login mantenimiento: kenny / PIN 141414\n--\n-- Si algo falla, al final hay consultas de verificación.\n--\n-- Módulos integrados (pedidos, RRHH, nómina, recepciones): después ejecuta\n-- docs/SUPABASE-SQL-INTEGRACION.sql — ver docs/PROMPT-SQL-SUPABASE-INTEGRACION.md\n-- =============================================================================\n\ncreate extension if not exists \"pgcrypto\" with schema extensions;\n\n-- ─── Utilidades ─────────────────────────────────────────────────────────────\n\ncreate or replace function public.crozzo_enable_pos_rls(p_table text)\nreturns void\nlanguage plpgsql\nas $$\nbegin\n  if not exists (\n    select 1 from information_schema.tables\n    where table_schema = 'public' and table_name = p_table\n  ) then\n    return;\n  end if;\n  execute format('alter table public.%I enable row level security', p_table);\n  execute format('drop policy if exists crozzo_pos_all on public.%I', p_table);\n  execute format(\n    'create policy crozzo_pos_all on public.%I for all to anon, authenticated using (true) with check (true)',\n    p_table\n  );\nend;\n$$;\n\ncreate or replace function public.crozzo_add_col_if_missing(\n  p_table text,\n  p_column text,\n  p_type text default 'text'\n)\nreturns void\nlanguage plpgsql\nas $$\nbegin\n  if not exists (\n    select 1 from information_schema.tables\n    where table_schema = 'public' and table_name = p_table\n  ) then\n    return;\n  end if;\n  if not exists (\n    select 1 from information_schema.columns\n    where table_schema = 'public' and table_name = p_table and column_name = p_column\n  ) then\n    execute format('alter table public.%I add column %I %s', p_table, p_column, p_type);\n  end if;\nexception\n  when undefined_table then null;\n  when duplicate_column then null;\nend;\n$$;\n\n-- Repara permisos de todas las tablas public (ejecutar cuando hay 401/403/RLS)\ncreate or replace function public.crozzo_fix_all_grants()\nreturns void\nlanguage plpgsql\nas $$\ndeclare\n  r record;\nbegin\n  grant usage on schema public to anon, authenticated;\n  for r in\n    select tablename from pg_tables where schemaname = 'public'\n  loop\n    execute format('grant select, insert, update, delete on public.%I to anon, authenticated', r.tablename);\n    perform public.crozzo_enable_pos_rls(r.tablename);\n  end loop;\n  grant usage, select on all sequences in schema public to anon, authenticated;\nend;\n$$;\n\n-- =============================================================================\n-- TABLAS\n-- =============================================================================\n\ncreate table if not exists public.products (\n  id bigint primary key,\n  name text not null default 'Producto',\n  price numeric(14, 2) not null default 0,\n  iva_rate numeric(8, 4) not null default 0,\n  icon text default '📦',\n  category_slug text default 'general',\n  barcode text,\n  sku text,\n  stock numeric(14, 3),\n  area_comanda text,\n  business_id text,\n  opcion_grupos jsonb,\n  arrastra_productos jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.devices (\n  id uuid primary key default gen_random_uuid(),\n  device_id text,\n  name text not null default 'POS',\n  type text not null default 'central',\n  is_active boolean not null default true,\n  last_sync_at timestamptz,\n  business_id text,\n  created_at timestamptz not null default now()\n);\n\n-- Sincronización principal (logo, productos, clientes, empresa en JSON)\ncreate table if not exists public.company_config (\n  id text primary key,\n  tenant_snapshot jsonb,\n  config_json jsonb,\n  data jsonb,\n  settings jsonb,\n  business_id text,\n  location_id text default 'default',\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.pos_staff (\n  id text not null,\n  location_id text not null default 'default',\n  nombre text not null,\n  rol text not null default 'caja',\n  activo boolean not null default true,\n  permisos jsonb not null default '{}'::jsonb,\n  config_dispositivo jsonb not null default '{}'::jsonb,\n  pin_hash text,\n  pin_version integer not null default 1,\n  session_epoch bigint not null default 0,\n  updated_at timestamptz not null default now(),\n  primary key (id, location_id)\n);\n\ncreate table if not exists public.clients (\n  id uuid primary key default gen_random_uuid(),\n  nombre text,\n  documento text,\n  email text,\n  telefono text,\n  data jsonb default '{}'::jsonb,\n  business_id text,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.categories (\n  id text primary key,\n  nombre text not null,\n  slug text,\n  data jsonb default '{}'::jsonb,\n  business_id text,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.taxes (\n  id text primary key,\n  nombre text not null,\n  rate numeric(8, 4) not null default 0,\n  data jsonb default '{}'::jsonb,\n  business_id text,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.sales (\n  id uuid primary key default gen_random_uuid(),\n  device_id uuid,\n  total_amount numeric(14, 2),\n  total numeric(14, 2),\n  currency text default 'COP',\n  status text default 'emitida',\n  estado text,\n  snapshot jsonb,\n  items jsonb,\n  meta jsonb,\n  payload jsonb,\n  business_id text,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists public.sale_items (\n  id uuid primary key default gen_random_uuid(),\n  sale_id uuid references public.sales (id) on delete cascade,\n  product_id bigint references public.products (id) on delete set null,\n  qty numeric(12, 3) not null default 1,\n  unit_price numeric(14, 2) not null default 0,\n  line_total numeric(14, 2) not null default 0,\n  data jsonb default '{}'::jsonb\n);\n\ncreate table if not exists public.comandas (\n  id uuid primary key default gen_random_uuid(),\n  device_id uuid,\n  location_id text default 'default',\n  status text default 'open',\n  payload jsonb not null default '{}'::jsonb,\n  business_id text,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.sync_queue (\n  id text primary key,\n  device_id uuid,\n  operation text not null default 'sync',\n  table_name text not null default 'unknown',\n  payload jsonb not null default '{}'::jsonb,\n  status text not null default 'pending',\n  type text,\n  transaction_id text,\n  business_id text,\n  created_at timestamptz not null default now(),\n  synced_at timestamptz\n);\n\ncreate table if not exists public.audit_logs (\n  id uuid primary key default gen_random_uuid(),\n  device_id uuid,\n  event_type text,\n  detail text,\n  meta jsonb default '{}'::jsonb,\n  business_id text,\n  created_at timestamptz not null default now()\n);\n\n-- Cierres de turno / arqueo (copia inmutable en nube)\ncreate table if not exists public.shift_closes (\n  id uuid primary key default gen_random_uuid(),\n  device_id uuid,\n  business_date text,\n  shift_type text,\n  shift_id text,\n  closed_at timestamptz not null default now(),\n  closed_by text,\n  closed_by_id text,\n  sales_count integer,\n  total_sales numeric(14, 2),\n  cash_sales numeric(14, 2),\n  fondo numeric(14, 2),\n  expected numeric(14, 2),\n  actual numeric(14, 2),\n  diff numeric(14, 2),\n  auto_closed boolean not null default false,\n  facturas_hash text,\n  notes text,\n  record_json jsonb not null default '{}'::jsonb,\n  business_id text,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists public.dian_config (\n  id text primary key default 'default',\n  config_json jsonb not null default '{}'::jsonb,\n  business_id text,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.profiles (\n  id uuid primary key,\n  email text,\n  role text default 'cajero',\n  session_epoch bigint default 0,\n  data jsonb default '{}'::jsonb,\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists public.device_configs (\n  id uuid primary key default gen_random_uuid(),\n  business_id text,\n  device_id text not null,\n  role text,\n  server_ip text,\n  central_ip text,\n  port integer default 3000,\n  config_json jsonb not null default '{}'::jsonb,\n  last_seen timestamptz default now()\n);\n\n-- Mantenimiento (kenny / 141414)\ncreate table if not exists public.crozzo_pos_owners (\n  location_id text not null default 'default',\n  login_id text not null,\n  nombre text not null default 'Mantenimiento',\n  pin_hash text not null,\n  session_epoch bigint not null default 0,\n  updated_at timestamptz not null default now(),\n  primary key (location_id, login_id)\n);\n\n-- Tabla extra que a veces existe en proyectos viejos (compatibilidad)\ncreate table if not exists public.pos_system_owner (\n  id text primary key default 'default',\n  login_id text,\n  pin_hash text,\n  data jsonb default '{}'::jsonb,\n  updated_at timestamptz not null default now()\n);\n\n-- =============================================================================\n-- MIGRACIÓN DE COLUMNAS (tablas creadas antes)\n-- =============================================================================\n\ndo $$\nbegin\n  perform public.crozzo_add_col_if_missing('products', 'name', 'text');\n  perform public.crozzo_add_col_if_missing('products', 'nombre', 'text');\n  perform public.crozzo_add_col_if_missing('products', 'price', 'numeric(14,2) default 0');\n  perform public.crozzo_add_col_if_missing('products', 'precio', 'numeric(14,2) default 0');\n  perform public.crozzo_add_col_if_missing('products', 'iva_rate', 'numeric(8,4) default 0');\n  perform public.crozzo_add_col_if_missing('products', 'icon', 'text');\n  perform public.crozzo_add_col_if_missing('products', 'category_slug', 'text');\n  perform public.crozzo_add_col_if_missing('products', 'business_id', 'text');\n  perform public.crozzo_add_col_if_missing('products', 'updated_at', 'timestamptz default now()');\n\n  perform public.crozzo_add_col_if_missing('devices', 'device_id', 'text');\n  perform public.crozzo_add_col_if_missing('devices', 'name', 'text');\n  perform public.crozzo_add_col_if_missing('devices', 'type', 'text default ''central''');\n  perform public.crozzo_add_col_if_missing('devices', 'is_active', 'boolean default true');\n  perform public.crozzo_add_col_if_missing('devices', 'last_sync_at', 'timestamptz');\n\n  perform public.crozzo_add_col_if_missing('company_config', 'tenant_snapshot', 'jsonb');\n  perform public.crozzo_add_col_if_missing('company_config', 'config_json', 'jsonb');\n  perform public.crozzo_add_col_if_missing('company_config', 'data', 'jsonb');\n  perform public.crozzo_add_col_if_missing('company_config', 'settings', 'jsonb');\n  perform public.crozzo_add_col_if_missing('company_config', 'location_id', 'text default ''default''');\n  perform public.crozzo_add_col_if_missing('company_config', 'updated_at', 'timestamptz default now()');\n\n  perform public.crozzo_add_col_if_missing('pos_staff', 'location_id', 'text default ''default''');\n  perform public.crozzo_add_col_if_missing('pos_staff', 'pin_hash', 'text');\n  perform public.crozzo_add_col_if_missing('pos_staff', 'updated_at', 'timestamptz default now()');\n\n  perform public.crozzo_add_col_if_missing('clients', 'nombre', 'text');\n  perform public.crozzo_add_col_if_missing('clients', 'documento', 'text');\n  perform public.crozzo_add_col_if_missing('clients', 'data', 'jsonb default ''{}''::jsonb');\n\n  perform public.crozzo_add_col_if_missing('sync_queue', 'device_id', 'uuid');\n  perform public.crozzo_add_col_if_missing('sync_queue', 'payload', 'jsonb default ''{}''::jsonb');\n\n  perform public.crozzo_add_col_if_missing('shift_closes', 'business_date', 'text');\n  perform public.crozzo_add_col_if_missing('shift_closes', 'facturas_hash', 'text');\n  perform public.crozzo_add_col_if_missing('shift_closes', 'record_json', 'jsonb default ''{}''::jsonb');\nend $$;\n\n-- Relajar check de type en devices si existe y bloquea inserts\ndo $$\nbegin\n  alter table public.devices drop constraint if exists devices_type_check;\nexception when others then null;\nend $$;\n\n-- Índices\ncreate index if not exists devices_device_id_idx on public.devices (device_id);\ncreate unique index if not exists devices_device_id_unique on public.devices (device_id)\n  where device_id is not null;\ncreate index if not exists pos_staff_location_idx on public.pos_staff (location_id);\ncreate index if not exists idx_shift_closes_business_date\n  on public.shift_closes (business_date desc, closed_at desc);\ncreate index if not exists idx_shift_closes_device\n  on public.shift_closes (device_id, closed_at desc);\n\n-- =============================================================================\n-- RPC MANTENIMIENTO\n-- =============================================================================\n\ncreate or replace function public.crozzo_owner_setup(\n  p_location_id text default 'default',\n  p_login text default 'kenny',\n  p_pin text default '141414',\n  p_nombre text default 'Mantenimiento'\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  loc text := coalesce(nullif(trim(p_location_id), ''), 'default');\n  lid text := lower(trim(coalesce(p_login, 'kenny')));\nbegin\n  if length(trim(coalesce(p_pin, ''))) < 4 then\n    return jsonb_build_object('ok', false, 'error', 'pin_corto');\n  end if;\n  insert into public.crozzo_pos_owners (location_id, login_id, nombre, pin_hash, session_epoch, updated_at)\n  values (loc, lid, coalesce(nullif(trim(p_nombre), ''), 'Mantenimiento'), extensions.crypt(p_pin, extensions.gen_salt('bf')), 0, now())\n  on conflict (location_id, login_id) do update set\n    nombre = excluded.nombre,\n    pin_hash = excluded.pin_hash,\n    updated_at = now();\n  return jsonb_build_object('ok', true, 'location_id', loc, 'login_id', lid);\nend;\n$$;\n\ncreate or replace function public.crozzo_owner_exists(p_location_id text default 'default')\nreturns boolean\nlanguage sql\nsecurity definer\nset search_path = public\nstable\nas $$\n  select exists (\n    select 1 from public.crozzo_pos_owners o\n    where o.location_id = coalesce(nullif(trim(p_location_id), ''), 'default')\n  );\n$$;\n\ncreate or replace function public.crozzo_owner_status(p_location_id text, p_login text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nstable\nas $$\ndeclare\n  rec public.crozzo_pos_owners%rowtype;\n  loc text := coalesce(nullif(trim(p_location_id), ''), 'default');\nbegin\n  select * into rec from public.crozzo_pos_owners o\n  where o.location_id = loc and lower(o.login_id) = lower(trim(coalesce(p_login, '')));\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n  return jsonb_build_object('ok', true, 'login_id', rec.login_id, 'nombre', rec.nombre, 'session_epoch', rec.session_epoch);\nend;\n$$;\n\ncreate or replace function public.crozzo_owner_login(p_location_id text, p_login text, p_pin text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  rec public.crozzo_pos_owners%rowtype;\n  loc text := coalesce(nullif(trim(p_location_id), ''), 'default');\n  new_epoch bigint;\nbegin\n  select * into rec from public.crozzo_pos_owners o\n  where o.location_id = loc and lower(o.login_id) = lower(trim(coalesce(p_login, '')));\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n  if rec.pin_hash is null or extensions.crypt(p_pin, rec.pin_hash) <> rec.pin_hash then\n    return jsonb_build_object('ok', false, 'error', 'invalid');\n  end if;\n  new_epoch := coalesce(rec.session_epoch, 0) + 1;\n  update public.crozzo_pos_owners set session_epoch = new_epoch, updated_at = now()\n  where location_id = rec.location_id and login_id = rec.login_id;\n  return jsonb_build_object('ok', true, 'login_id', rec.login_id, 'nombre', rec.nombre, 'rol', 'superadmin', 'session_epoch', new_epoch);\nend;\n$$;\n\ncreate or replace function public.crozzo_owner_change_pin(p_location_id text, p_login text, p_old_pin text, p_new_pin text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  rec public.crozzo_pos_owners%rowtype;\n  loc text := coalesce(nullif(trim(p_location_id), ''), 'default');\n  new_epoch bigint;\nbegin\n  if length(trim(coalesce(p_new_pin, ''))) < 4 then\n    return jsonb_build_object('ok', false, 'error', 'pin_corto');\n  end if;\n  select * into rec from public.crozzo_pos_owners o\n  where o.location_id = loc and lower(o.login_id) = lower(trim(coalesce(p_login, '')));\n  if not found then\n    return jsonb_build_object('ok', false, 'error', 'not_found');\n  end if;\n  if rec.pin_hash is null or extensions.crypt(p_old_pin, rec.pin_hash) <> rec.pin_hash then\n    return jsonb_build_object('ok', false, 'error', 'invalid');\n  end if;\n  new_epoch := coalesce(rec.session_epoch, 0) + 1;\n  update public.crozzo_pos_owners set\n    pin_hash = extensions.crypt(p_new_pin, extensions.gen_salt('bf')),\n    session_epoch = new_epoch,\n    updated_at = now()\n  where location_id = rec.location_id and login_id = rec.login_id;\n  return jsonb_build_object('ok', true, 'session_epoch', new_epoch);\nend;\n$$;\n\n-- =============================================================================\n-- PERMISOS (RLS abierto para anon = clave pública del POS)\n-- =============================================================================\n\nselect public.crozzo_fix_all_grants();\n\ngrant execute on function public.crozzo_owner_setup(text, text, text, text) to anon, authenticated;\ngrant execute on function public.crozzo_owner_exists(text) to anon, authenticated;\ngrant execute on function public.crozzo_owner_status(text, text) to anon, authenticated;\ngrant execute on function public.crozzo_owner_login(text, text, text) to anon, authenticated;\ngrant execute on function public.crozzo_owner_change_pin(text, text, text, text) to anon, authenticated;\n\nalter default privileges in schema public\n  grant select, insert, update, delete on tables to anon, authenticated;\n\n-- =============================================================================\n-- REALTIME (opcional — no falla si no está disponible)\n-- =============================================================================\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'company_config', 'pos_staff', 'products', 'clients', 'devices'\n  ]\n  loop\n    begin\n      execute format('alter table public.%I replica identity full', t);\n    exception when others then null;\n    end;\n    begin\n      execute format('alter publication supabase_realtime add table public.%I', t);\n    exception when duplicate_object then null;\n      when others then null;\n    end;\n  end loop;\nend $$;\n\n-- =============================================================================\n-- DATOS INICIALES\n-- =============================================================================\n\nselect public.crozzo_owner_setup('default', 'kenny', '141414', 'Mantenimiento');\n\n-- Fila inicial company_config (id TEXT o UUID según tu tabla — evita error 22P02)\ndo $$\ndeclare\n  id_udt text;\nbegin\n  select c.udt_name\n  into id_udt\n  from information_schema.columns c\n  where c.table_schema = 'public'\n    and c.table_name = 'company_config'\n    and c.column_name = 'id';\n\n  if id_udt = 'uuid' then\n    insert into public.company_config (id, location_id, tenant_snapshot, config_json, updated_at)\n    values (\n      '00000000-0000-0000-0000-000000000001'::uuid,\n      'default',\n      '{}'::jsonb,\n      '{\"pos_snapshot\":{}}'::jsonb,\n      now()\n    )\n    on conflict (id) do update set updated_at = now();\n  elsif id_udt in ('text', 'character varying') then\n    insert into public.company_config (id, location_id, tenant_snapshot, config_json, updated_at)\n    values ('default', 'default', '{}'::jsonb, '{\"pos_snapshot\":{}}'::jsonb, now())\n    on conflict (id) do update set updated_at = now();\n  else\n    raise notice 'company_config.id tipo % — seed omitido', id_udt;\n  end if;\nexception\n  when others then\n    raise notice 'company_config seed: %', sqlerrm;\nend $$;\n\nnotify pgrst, 'reload schema';\n\n-- =============================================================================\n-- VERIFICACIÓN (debe devolver filas; si count = 0 hay problema de permisos)\n-- =============================================================================\n\n-- Políticas RLS por tabla:\nselect tablename, policyname, roles, cmd\nfrom pg_policies\nwhere schemaname = 'public' and policyname = 'crozzo_pos_all'\norder by 1;\n\n-- Tipos de id importantes:\nselect table_name, column_name, data_type, udt_name\nfrom information_schema.columns\nwhere table_schema = 'public'\n  and table_name in ('company_config', 'products')\n  and column_name = 'id';\n\n-- Conteos (después de «Subir todo» en el POS):\nselect 'company_config' as tabla, count(*)::int as filas from public.company_config\nunion all\nselect 'pos_staff', count(*)::int from public.pos_staff\nunion all\nselect 'products', count(*)::int from public.products\nunion all\nselect 'clients', count(*)::int from public.clients;\n\n-- =============================================================================\n-- REPARACIÓN EXTREMA (solo si products sigue dando error 400)\n-- Descomenta las 2 líneas, ejecuta, y vuelve a ejecutar TODO el archivo desde arriba.\n-- =============================================================================\n-- drop table if exists public.products cascade;\n-- drop table if exists public.sale_items cascade;\n"},{"key":"integracion","file":"docs/SUPABASE-SQL-INTEGRACION.sql","title":"2. Integración operativa","desc":"Empleados, marcaciones, pedidos internos y nómina.","required":true,"order":2,"sql":"-- =============================================================================\r\n-- CROZZO POS — MÓDULOS INTEGRADOS (pedidos, RRHH, nómina, recepciones QyC)\r\n-- =============================================================================\r\n-- Ejecutar DESPUÉS de docs/SUPABASE-SQL-EDITOR.sql en el mismo proyecto Supabase.\r\n-- Luego: Multi-dispositivo → Cloud ON → Guardar → F5 en el POS.\r\n-- =============================================================================\r\n\r\ncreate extension if not exists \"pgcrypto\" with schema extensions;\r\n\r\n-- Reutiliza crozzo_enable_pos_rls y crozzo_fix_all_grants del script base.\r\n\r\n-- ─── Empleados (control de acceso / nómina) ───────────────────────────────────\r\n\r\ncreate table if not exists public.crozzo_empleados (\r\n  id bigint generated by default as identity primary key,\r\n  business_id text,\r\n  name text not null default '',\r\n  full_name text,\r\n  pin text not null default '',\r\n  cargo text,\r\n  eps text,\r\n  ingreso text,\r\n  tel text,\r\n  correo text,\r\n  activo boolean not null default true,\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists crozzo_empleados_bid_idx on public.crozzo_empleados (business_id);\r\ncreate unique index if not exists crozzo_empleados_pin_bid_uq\r\n  on public.crozzo_empleados (business_id, pin) where pin is not null and pin <> '';\r\n\r\n-- ─── Marcaciones entrada/salida ───────────────────────────────────────────────\r\n\r\ncreate table if not exists public.crozzo_marcaciones (\r\n  id bigint generated by default as identity primary key,\r\n  business_id text,\r\n  empleado_id bigint not null references public.crozzo_empleados (id) on delete cascade,\r\n  nombre text,\r\n  cargo text,\r\n  tipo text not null check (tipo in ('entrada', 'salida')),\r\n  fecha date not null,\r\n  timestamp bigint not null,\r\n  foto_url text,\r\n  notas text,\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists crozzo_marcaciones_fecha_idx on public.crozzo_marcaciones (fecha desc);\r\ncreate index if not exists crozzo_marcaciones_emp_fecha_idx on public.crozzo_marcaciones (empleado_id, fecha);\r\n\r\n-- ─── Config RRHH (horarios, plan semanal, nómina, logo) en un JSON por tenant ─\r\n\r\ncreate table if not exists public.crozzo_rrhh_config (\r\n  id text primary key,\r\n  business_id text,\r\n  payload jsonb not null default '{}'::jsonb,\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- ─── Pedidos internos (cocina / bar / panadería / desechables) ────────────────\r\n\r\ncreate table if not exists public.crozzo_pedidos_internos (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text,\r\n  responsable text not null default '',\r\n  fecha_pedido date,\r\n  area text not null default 'cocina',\r\n  items jsonb not null default '[]'::jsonb,\r\n  observaciones text,\r\n  telegram_ok boolean default false,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists crozzo_pedidos_internos_created_idx\r\n  on public.crozzo_pedidos_internos (created_at desc);\r\n\r\n-- ─── Integración (Telegram pedidos, claves admin kiosk, etc.) ─────────────────\r\n\r\ncreate table if not exists public.crozzo_integracion_config (\r\n  id text primary key,\r\n  business_id text,\r\n  payload jsonb not null default '{}'::jsonb,\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- ─── Nómina por quincena (compatible con planilla 2026) ───────────────────────\r\n\r\ncreate table if not exists public.crozzo_nomina_periodos (\r\n  id text primary key,\r\n  business_id text,\r\n  clave text not null,\r\n  anio int,\r\n  mes int,\r\n  quincena int check (quincena in (1, 2)),\r\n  filas jsonb not null default '{}'::jsonb,\r\n  totales jsonb default '{}'::jsonb,\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists crozzo_nomina_periodos_clave_idx\r\n  on public.crozzo_nomina_periodos (business_id, clave);\r\n\r\n-- ─── Operaciones QyC: proveedores y recepciones (MVP integrado) ───────────────\r\n\r\ncreate table if not exists public.crozzo_proveedores_ops (\r\n  id bigint generated by default as identity primary key,\r\n  business_id text,\r\n  nombre text not null default '',\r\n  nit text,\r\n  contacto text,\r\n  activo boolean not null default true,\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.crozzo_recepciones (\r\n  id bigint generated by default as identity primary key,\r\n  business_id text,\r\n  proveedor_id bigint references public.crozzo_proveedores_ops (id) on delete set null,\r\n  proveedor_nombre text,\r\n  fecha date not null default (current_date),\r\n  valor_factura numeric(14, 2) default 0,\r\n  estado_recepcion text default 'registrada',\r\n  peso_bascula_kg numeric(12, 3),\r\n  foto_url text,\r\n  comprobante_pago_url text,\r\n  pagada_en timestamptz,\r\n  notas text,\r\n  registrado_por text,\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists crozzo_recepciones_fecha_idx on public.crozzo_recepciones (fecha desc);\r\n\r\n-- ─── RLS y permisos (mismo patrón que el POS) ─────────────────────────────────\r\n\r\nselect public.crozzo_enable_pos_rls('crozzo_empleados');\r\nselect public.crozzo_enable_pos_rls('crozzo_marcaciones');\r\nselect public.crozzo_enable_pos_rls('crozzo_rrhh_config');\r\nselect public.crozzo_enable_pos_rls('crozzo_pedidos_internos');\r\nselect public.crozzo_enable_pos_rls('crozzo_integracion_config');\r\nselect public.crozzo_enable_pos_rls('crozzo_nomina_periodos');\r\nselect public.crozzo_enable_pos_rls('crozzo_proveedores_ops');\r\nselect public.crozzo_enable_pos_rls('crozzo_recepciones');\r\n\r\nselect public.crozzo_fix_all_grants();\r\n\r\n-- Bucket opcional para fotos de marcación (crear en Dashboard → Storage si lo usa):\r\n--   nombre: fotos-marcaciones   público: sí (o signed URLs según política)\r\n\r\n-- Verificación rápida:\r\n-- select tablename from pg_tables where schemaname = 'public' and tablename like 'crozzo_%' order by 1;\r\n"},{"key":"qyc","file":"docs/SUPABASE-SQL-QYC.sql","title":"3. Compras y facturas proveedor (QyC)","desc":"Proveedores, recepciones, facturas y flujo oficina.","required":true,"order":3,"sql":"-- =============================================================================\r\n-- CROZZO POS — Esquema QyC (Crozzo QyC.html / recepciones, cortes, oficina)\r\n-- Ejecutar DESPUÉS de SUPABASE-SQL-EDITOR.sql y SUPABASE-SQL-INTEGRACION.sql\r\n-- =============================================================================\r\n\r\n-- Usuarios del módulo QyC (login PIN en la app)\r\ncreate table if not exists public.usuarios (\r\n  id bigint generated by default as identity primary key,\r\n  nombre text not null default '',\r\n  pin text not null default '',\r\n  rol text not null default 'auxiliar',\r\n  permisos jsonb not null default '{}'::jsonb,\r\n  notas text,\r\n  activo boolean not null default true,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate unique index if not exists usuarios_pin_uq on public.usuarios (pin) where activo = true;\r\n\r\n-- Proveedores (QyC usa tabla proveedores, no crozzo_proveedores_ops)\r\ncreate table if not exists public.proveedores (\r\n  id bigint generated by default as identity primary key,\r\n  nombre text not null default '',\r\n  tipo_carne text,\r\n  telefono text,\r\n  nit text,\r\n  precio_por_kg numeric(14, 4) default 0,\r\n  factura_por_unidad boolean default false,\r\n  gramaje_unidad_g int,\r\n  activo boolean not null default true,\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.materias_primas (\r\n  id bigint generated by default as identity primary key,\r\n  nombre text not null default '',\r\n  categoria text,\r\n  merma_coccion_pct numeric(8, 4) default 0,\r\n  merma_porcionado_pct numeric(8, 4) default 0,\r\n  activo boolean not null default true,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.productos (\r\n  id bigint generated by default as identity primary key,\r\n  nombre text not null default '',\r\n  gramaje_porcion numeric(14, 3),\r\n  materia_prima_id bigint references public.materias_primas (id) on delete set null,\r\n  activo boolean not null default true,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.recepciones (\r\n  id bigint generated by default as identity primary key,\r\n  proveedor_id bigint references public.proveedores (id) on delete set null,\r\n  materia_prima_id bigint references public.materias_primas (id) on delete set null,\r\n  fecha date not null default (current_date),\r\n  peso_bascula_kg numeric(14, 3) default 0,\r\n  precio_por_kg numeric(14, 4),\r\n  valor_factura numeric(14, 2),\r\n  estado_recepcion text default 'pendiente_jefe',\r\n  foto_url text,\r\n  comprobante_pago_url text,\r\n  pagada_en timestamptz,\r\n  notas text,\r\n  registrado_por text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists recepciones_fecha_idx on public.recepciones (fecha desc);\r\n\r\ncreate table if not exists public.cortes_recepcion (\r\n  id bigint generated by default as identity primary key,\r\n  recepcion_id bigint references public.recepciones (id) on delete cascade,\r\n  proveedor_id bigint references public.proveedores (id) on delete set null,\r\n  materia_prima_id bigint references public.materias_primas (id) on delete set null,\r\n  fecha date,\r\n  peso_kg numeric(14, 3) default 0,\r\n  precio_por_kg numeric(14, 4),\r\n  registrado_por text,\r\n  notas text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.facturas (\r\n  id bigint generated by default as identity primary key,\r\n  proveedor_id bigint references public.proveedores (id) on delete set null,\r\n  recepcion_id bigint references public.recepciones (id) on delete set null,\r\n  fecha date not null default (current_date),\r\n  numero_factura text,\r\n  valor numeric(14, 2) default 0,\r\n  estado text default 'pendiente_oficina',\r\n  metodo_pago text default 'transferencia',\r\n  foto_url text,\r\n  registrado_por text,\r\n  notas text,\r\n  pagada_en date,\r\n  fecha_pago date,\r\n  data_extraida jsonb,\r\n  extraccion_status text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists facturas_fecha_idx on public.facturas (fecha desc);\r\ncreate index if not exists facturas_recepcion_idx on public.facturas (recepcion_id);\r\n\r\ncreate table if not exists public.lotes_procesado (\r\n  id bigint generated by default as identity primary key,\r\n  materia_prima_id bigint references public.materias_primas (id) on delete set null,\r\n  fecha date not null default (current_date),\r\n  peso_entrada_kg numeric(14, 3) default 0,\r\n  diferencia_gr numeric(14, 3),\r\n  merma_coccion_real_pct numeric(8, 4),\r\n  merma_porcionado_real_pct numeric(8, 4),\r\n  peso_total_porciones_gr numeric(14, 3),\r\n  procesado_por text,\r\n  notas text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.porciones_producidas (\r\n  id bigint generated by default as identity primary key,\r\n  lote_id bigint references public.lotes_procesado (id) on delete cascade,\r\n  producto_id bigint references public.productos (id) on delete set null,\r\n  cantidad int default 0,\r\n  peso_gr numeric(14, 3),\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.conteos_inventario (\r\n  id bigint generated by default as identity primary key,\r\n  producto_id bigint references public.productos (id) on delete set null,\r\n  fecha_conteo date not null default (current_date),\r\n  stock_teorico numeric(14, 3),\r\n  stock_fisico numeric(14, 3),\r\n  contado_por text,\r\n  notas text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.receta_ingredientes (\r\n  id bigint generated by default as identity primary key,\r\n  plato_id bigint,\r\n  producto_id bigint references public.productos (id) on delete cascade,\r\n  cantidad_gr numeric(14, 3) default 0,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.pagos_internos (\r\n  id bigint generated by default as identity primary key,\r\n  proveedor_id bigint references public.proveedores (id) on delete set null,\r\n  mes text,\r\n  valor numeric(14, 2) default 0,\r\n  estado text,\r\n  notas text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.configuracion (\r\n  clave text primary key,\r\n  valor text,\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\n-- Usuario admin inicial (PIN 141414 — cambiar en la app Usuarios)\r\ninsert into public.usuarios (nombre, pin, rol, permisos, activo)\r\nselect 'Administrador', '141414', 'admin',\r\n  '{\"recepcion\":true,\"procesado\":true,\"conteo\":true,\"ventas\":true,\"dashboard\":true,\"catalogo\":true,\"proveedores\":true,\"oficina\":true,\"usuarios\":true}'::jsonb,\r\n  true\r\nwhere not exists (select 1 from public.usuarios where pin = '141414' and activo = true);\r\n\r\nselect public.crozzo_enable_pos_rls('usuarios');\r\nselect public.crozzo_enable_pos_rls('proveedores');\r\nselect public.crozzo_enable_pos_rls('materias_primas');\r\nselect public.crozzo_enable_pos_rls('productos');\r\nselect public.crozzo_enable_pos_rls('recepciones');\r\nselect public.crozzo_enable_pos_rls('cortes_recepcion');\r\nselect public.crozzo_enable_pos_rls('facturas');\r\nselect public.crozzo_enable_pos_rls('lotes_procesado');\r\nselect public.crozzo_enable_pos_rls('porciones_producidas');\r\nselect public.crozzo_enable_pos_rls('conteos_inventario');\r\nselect public.crozzo_enable_pos_rls('receta_ingredientes');\r\nselect public.crozzo_enable_pos_rls('pagos_internos');\r\nselect public.crozzo_enable_pos_rls('configuracion');\r\n\r\nselect public.crozzo_fix_all_grants();\r\n\r\n-- Storage PDF/fotos oficina y facturas\r\ninsert into storage.buckets (id, name, public)\r\nvalues ('oficina-docs', 'oficina-docs', true)\r\non conflict (id) do update set public = true;\r\n\r\ndrop policy if exists crozzo_oficina_docs_select on storage.objects;\r\ndrop policy if exists crozzo_oficina_docs_insert on storage.objects;\r\n\r\ncreate policy crozzo_oficina_docs_select on storage.objects\r\n  for select to anon, authenticated using (bucket_id = 'oficina-docs');\r\n\r\ncreate policy crozzo_oficina_docs_insert on storage.objects\r\n  for insert to anon, authenticated with check (bucket_id = 'oficina-docs');\r\n"},{"key":"storage","file":"docs/SUPABASE-STORAGE-FOTOS-MARCACIONES.sql","title":"4. Storage (fotos y documentos)","desc":"Buckets oficina-docs y fotos-marcaciones con políticas.","required":true,"order":4,"sql":"-- Bucket para fotos de marcación (Control de acceso integrado)\r\n-- Ejecutar en Supabase → SQL Editor DESPUÉS de SUPABASE-SQL-INTEGRACION.sql\r\n--\r\n-- También puede crear el bucket en Dashboard → Storage → New bucket:\r\n--   ID: fotos-marcaciones   Public: ON\r\n\r\ninsert into storage.buckets (id, name, public)\r\nvalues ('fotos-marcaciones', 'fotos-marcaciones', true)\r\non conflict (id) do update set public = true;\r\n\r\n-- Políticas mínimas para anon (mismo patrón que el POS)\r\ndrop policy if exists crozzo_fotos_marc_select on storage.objects;\r\ndrop policy if exists crozzo_fotos_marc_insert on storage.objects;\r\n\r\ncreate policy crozzo_fotos_marc_select on storage.objects\r\n  for select to anon, authenticated\r\n  using (bucket_id = 'fotos-marcaciones');\r\n\r\ncreate policy crozzo_fotos_marc_insert on storage.objects\r\n  for insert to anon, authenticated\r\n  with check (bucket_id = 'fotos-marcaciones');\r\n"},{"key":"fix_tarjeta","file":"docs/SUPABASE-SQL-QYC-FIX-TARJETA.sql","title":"5. Corrección método pago tarjeta","desc":"Solo si ya tenía la base QyC antes de este fix.","required":false,"order":5,"sql":"-- Ejecutar en el MISMO proyecto Supabase del POS (después de SUPABASE-SQL-QYC.sql).\r\n-- Corrige: violates check constraint \"facturas_metodo_pago_chk\" al pagar con tarjeta.\r\n\r\nALTER TABLE public.facturas\r\n  DROP CONSTRAINT IF EXISTS facturas_metodo_pago_chk;\r\n\r\nALTER TABLE public.facturas\r\n  ADD CONSTRAINT facturas_metodo_pago_chk\r\n  CHECK (\r\n    metodo_pago IS NULL\r\n    OR metodo_pago IN ('transferencia', 'efectivo', 'tarjeta')\r\n  );\r\n"},{"key":"merma_alertas","file":"docs/SUPABASE-SQL-QYC-MERMA-ALERTAS.sql","title":"6. Merma y alertas de inventario","desc":"Alertas automáticas en compras/inventario.","required":false,"order":6,"sql":"-- =============================================================================\r\n-- CROZZO QyC — Alertas de merma programables + responsables en cortes\r\n-- Ejecutar DESPUÉS de SUPABASE-SQL-QYC.sql\r\n-- =============================================================================\r\n\r\n-- Materia prima: merma objetivo (si > 0) o suma de cocción+porcionado; tolerancia ±% para alertas\r\nalter table public.materias_primas\r\n  add column if not exists merma_objetivo_pct numeric(8, 4) default 0;\r\n\r\nalter table public.materias_primas\r\n  add column if not exists merma_alerta_tol_pct numeric(8, 4) default 2;\r\n\r\ncomment on column public.materias_primas.merma_objetivo_pct is\r\n  'Merma total programada (%). Si es 0, se usa merma_coccion_pct + merma_porcionado_pct';\r\n\r\ncomment on column public.materias_primas.merma_alerta_tol_pct is\r\n  'Tolerancia ±%: alerta en dashboard si la merma real sale fuera de [objetivo - tol, objetivo + tol]';\r\n\r\n-- Cortes de recepción: varios responsables en la sesión (texto separado por comas)\r\nalter table public.cortes_recepcion\r\n  add column if not exists responsables text;\r\n\r\ncomment on column public.cortes_recepcion.responsables is\r\n  'Nombres de quienes registraron el corte (uno o varios), separados por coma';\r\n"},{"key":"costos","file":"docs/SUPABASE-SQL-COSTOS.sql","title":"7. Sistema de costos","desc":"Matriz de precios, inventario ledger y cola planilla.","required":false,"order":7,"sql":"-- Crozzo POS — Sistema de costos (matriz, inventario ledger, cola planilla)\r\n-- Ejecutar DESPUÉS de: SUPABASE-SQL-EDITOR.sql, INTEGRACION.sql, QYC.sql\r\n\r\n-- ── F1 · Matriz de precios ───────────────────────────────────────────────────\r\n\r\ncreate table if not exists public.crozzo_matriz_precios (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  nombre text not null default 'Matriz principal',\r\n  estado text not null default 'borrador'\r\n    check (estado in ('borrador', 'revision', 'aprobada', 'vigente', 'historica')),\r\n  vigencia_desde timestamptz,\r\n  vigencia_hasta timestamptz,\r\n  notas text,\r\n  creado_por text,\r\n  aprobado_por text,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n);\r\n\r\ncreate table if not exists public.crozzo_matriz_precios_items (\r\n  id uuid primary key default gen_random_uuid(),\r\n  matriz_id uuid not null references public.crozzo_matriz_precios(id) on delete cascade,\r\n  ref_tipo text not null check (ref_tipo in ('producto_pos', 'producto_qyc', 'materia_prima', 'receta', 'corte')),\r\n  ref_id text not null,\r\n  nombre_display text not null,\r\n  costo_unitario numeric(14, 4) not null default 0,\r\n  margen_objetivo_pct numeric(8, 4) not null default 0,\r\n  precio_recomendado numeric(14, 2) not null default 0,\r\n  precio_decidido numeric(14, 2),\r\n  unidad text default 'und',\r\n  meta jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now(),\r\n  unique (matriz_id, ref_tipo, ref_id)\r\n);\r\n\r\ncreate table if not exists public.crozzo_matriz_programaciones (\r\n  id uuid primary key default gen_random_uuid(),\r\n  matriz_id uuid not null references public.crozzo_matriz_precios(id) on delete cascade,\r\n  fecha_vigencia date not null,\r\n  hora_vigencia time default '06:00:00',\r\n  estado text not null default 'programada'\r\n    check (estado in ('programada', 'aplicada', 'cancelada', 'fallida')),\r\n  aplicada_at timestamptz,\r\n  dispositivos_ok int default 0,\r\n  dispositivos_total int default 0,\r\n  log jsonb default '[]'::jsonb,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\n-- ── F3 · Inventario ledger ───────────────────────────────────────────────────\r\n\r\ncreate table if not exists public.crozzo_inventario_movimientos (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  fecha date not null default (current_date),\r\n  tipo text not null check (tipo in (\r\n    'inicial', 'entrada_proveedor', 'entrada_proceso', 'salida_venta',\r\n    'salida_merma', 'ajuste_conteo', 'ajuste_manual'\r\n  )),\r\n  ref_tipo text,\r\n  ref_id text,\r\n  producto_ref_tipo text check (producto_ref_tipo in ('producto_pos', 'producto_qyc', 'materia_prima')),\r\n  producto_ref_id text not null,\r\n  cantidad numeric(14, 4) not null,\r\n  unidad text default 'kg',\r\n  costo_unitario numeric(14, 4) default 0,\r\n  valor_total numeric(14, 2) generated always as (cantidad * costo_unitario) stored,\r\n  notas text,\r\n  usuario text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists idx_crozzo_inv_mov_fecha on public.crozzo_inventario_movimientos (business_id, fecha);\r\ncreate index if not exists idx_crozzo_inv_mov_prod on public.crozzo_inventario_movimientos (producto_ref_tipo, producto_ref_id);\r\n\r\ncreate table if not exists public.crozzo_inventario_cierres (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  fecha date not null,\r\n  inventario_inicial_valor numeric(14, 2) default 0,\r\n  entradas_valor numeric(14, 2) default 0,\r\n  salidas_valor numeric(14, 2) default 0,\r\n  teorico_final_valor numeric(14, 2) default 0,\r\n  conteo_fisico_valor numeric(14, 2),\r\n  diferencia_valor numeric(14, 2),\r\n  diferencia_pct numeric(8, 4),\r\n  estado text not null default 'abierto' check (estado in ('abierto', 'cerrado', 'auditado')),\r\n  cerrado_por text,\r\n  cerrado_at timestamptz,\r\n  detalle jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  unique (business_id, fecha)\r\n);\r\n\r\n-- ── F6 · Cola planilla (admin elige qué ingresar) ────────────────────────────\r\n\r\ncreate table if not exists public.crozzo_planilla_feed (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  origen text not null check (origen in ('ventas', 'compra', 'oficina', 'inventario', 'nomina', 'manual')),\r\n  fecha date not null default (current_date),\r\n  concepto text not null,\r\n  monto numeric(14, 2) not null default 0,\r\n  tipo_movimiento text not null default 'egreso' check (tipo_movimiento in ('ingreso', 'egreso')),\r\n  referencia_tipo text,\r\n  referencia_id text,\r\n  payload jsonb default '{}'::jsonb,\r\n  estado text not null default 'pendiente'\r\n    check (estado in ('pendiente', 'aceptado', 'rechazado', 'ingresado')),\r\n  revisado_por text,\r\n  revisado_at timestamptz,\r\n  planilla_periodo_id text,\r\n  planilla_dia date,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists idx_crozzo_planilla_feed_estado on public.crozzo_planilla_feed (business_id, estado, fecha desc);\r\n\r\n-- ── RLS (mismo patrón POS) ───────────────────────────────────────────────────\r\n\r\nselect public.crozzo_enable_pos_rls('crozzo_matriz_precios');\r\nselect public.crozzo_enable_pos_rls('crozzo_matriz_precios_items');\r\nselect public.crozzo_enable_pos_rls('crozzo_matriz_programaciones');\r\nselect public.crozzo_enable_pos_rls('crozzo_inventario_movimientos');\r\nselect public.crozzo_enable_pos_rls('crozzo_inventario_cierres');\r\nselect public.crozzo_enable_pos_rls('crozzo_planilla_feed');\r\n"},{"key":"reservorio","file":"docs/SUPABASE-SQL-RESERVORIO-UNIFICADO.sql","title":"8. Reservorio unificado","desc":"Cola sync offline→nube y snapshots del reservorio.","required":false,"order":8,"sql":"-- Crozzo POS — Reservorio unificado + flujos conectados\r\n-- Ejecutar EN ORDEN en SQL Editor de Supabase (proyecto del POS)\r\n--\r\n-- 1. docs/SUPABASE-SQL-EDITOR.sql\r\n-- 2. docs/SUPABASE-SQL-INTEGRACION.sql\r\n-- 3. docs/SUPABASE-SQL-QYC.sql\r\n-- 4. docs/SUPABASE-STORAGE-FOTOS-MARCACIONES.sql\r\n-- 5. docs/SUPABASE-SQL-QYC-FIX-TARJETA.sql\r\n-- 6. docs/SUPABASE-SQL-COSTOS.sql\r\n-- 7. ESTE ARCHIVO (reservorio + cola sync + puente proveedores)\r\n\r\n-- ── Puente proveedores POS ↔ QyC ───────────────────────────────────────────\r\n\r\nalter table if exists public.proveedores\r\n  add column if not exists pos_proveedor_id text,\r\n  add column if not exists categoria text default '',\r\n  add column if not exists activo boolean not null default true;\r\n\r\ncreate unique index if not exists idx_proveedores_pos_id\r\n  on public.proveedores (pos_proveedor_id)\r\n  where pos_proveedor_id is not null and pos_proveedor_id <> '';\r\n\r\ncomment on column public.proveedores.pos_proveedor_id is\r\n  'ID del proveedor en POS (proveedoresOC) para sincronizar offline → nube';\r\n\r\n-- ── Cola de sincronización (reservorio offline → nube) ───────────────────────\r\n\r\ncreate table if not exists public.crozzo_reservorio_sync_queue (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  op text not null check (op in ('insert', 'update', 'upsert', 'delete')),\r\n  tabla text not null,\r\n  payload jsonb not null default '{}'::jsonb,\r\n  estado text not null default 'pendiente'\r\n    check (estado in ('pendiente', 'procesando', 'ok', 'error')),\r\n  intentos int not null default 0,\r\n  error_msg text,\r\n  local_id text,\r\n  created_at timestamptz not null default now(),\r\n  processed_at timestamptz\r\n);\r\n\r\ncreate index if not exists idx_crozzo_sync_queue_pend\r\n  on public.crozzo_reservorio_sync_queue (business_id, estado, created_at desc);\r\n\r\n-- ── Snapshot reservorio (backup opcional por dispositivo) ────────────────────\r\n\r\ncreate table if not exists public.crozzo_reservorio_snapshots (\r\n  id uuid primary key default gen_random_uuid(),\r\n  business_id text not null default 'default',\r\n  device_id text,\r\n  version int not null default 1,\r\n  snapshot jsonb not null,\r\n  stats jsonb default '{}'::jsonb,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists idx_crozzo_reservorio_snap\r\n  on public.crozzo_reservorio_snapshots (business_id, created_at desc);\r\n\r\n-- ── Vista operativa: flujo compras conectado ─────────────────────────────────\r\n\r\ncreate or replace view public.crozzo_v_flujo_compras as\r\nselect\r\n  r.id as recepcion_id,\r\n  r.fecha as recepcion_fecha,\r\n  r.proveedor_id,\r\n  p.nombre as proveedor_nombre,\r\n  r.total as recepcion_total,\r\n  f.id as factura_id,\r\n  f.estado as factura_estado,\r\n  f.metodo_pago,\r\n  f.total as factura_total\r\nfrom public.recepciones r\r\nleft join public.proveedores p on p.id = r.proveedor_id\r\nleft join public.facturas f on f.recepcion_id = r.id;\r\n\r\ncomment on view public.crozzo_v_flujo_compras is\r\n  'Recepción → proveedor → factura oficina (cadena F4/F5)';\r\n\r\n-- ── RLS ──────────────────────────────────────────────────────────────────────\r\n\r\nselect public.crozzo_enable_pos_rls('crozzo_reservorio_sync_queue');\r\nselect public.crozzo_enable_pos_rls('crozzo_reservorio_snapshots');\r\n\r\n-- ── Función auxiliar: marcar sync procesado ──────────────────────────────────\r\n\r\ncreate or replace function public.crozzo_sync_queue_done(p_id uuid, p_ok boolean, p_error text default null)\r\nreturns void\r\nlanguage plpgsql\r\nsecurity definer\r\nas $$\r\nbegin\r\n  update public.crozzo_reservorio_sync_queue\r\n  set\r\n    estado = case when p_ok then 'ok' else 'error' end,\r\n    error_msg = p_error,\r\n    processed_at = now(),\r\n    intentos = intentos + 1\r\n  where id = p_id;\r\nend;\r\n$$;\r\n"},{"key":"shift_closes","file":"docs/SUPABASE-SQL-SHIFT-CLOSES.sql","title":"9. Cierres de turno","desc":"Tablas para cierre de caja sincronizado en nube.","required":false,"order":9,"sql":"-- =============================================================================\r\n-- Crozzo POS — Cierres de turno / arqueo (registro inmutable en nube)\r\n-- Ejecutar en Supabase SQL Editor después de SUPABASE-SQL-EDITOR.sql\r\n-- =============================================================================\r\n\r\ncreate table if not exists public.shift_closes (\r\n  id uuid primary key default gen_random_uuid(),\r\n  device_id uuid,\r\n  business_date text,\r\n  shift_type text,\r\n  shift_id text,\r\n  closed_at timestamptz not null default now(),\r\n  closed_by text,\r\n  closed_by_id text,\r\n  sales_count integer,\r\n  total_sales numeric(14, 2),\r\n  cash_sales numeric(14, 2),\r\n  fondo numeric(14, 2),\r\n  expected numeric(14, 2),\r\n  actual numeric(14, 2),\r\n  diff numeric(14, 2),\r\n  auto_closed boolean not null default false,\r\n  facturas_hash text,\r\n  notes text,\r\n  record_json jsonb not null default '{}'::jsonb,\r\n  business_id text,\r\n  created_at timestamptz not null default now()\r\n);\r\n\r\ncreate index if not exists idx_shift_closes_business_date\r\n  on public.shift_closes (business_date desc, closed_at desc);\r\n\r\ncreate index if not exists idx_shift_closes_device\r\n  on public.shift_closes (device_id, closed_at desc);\r\n\r\ncreate unique index if not exists idx_shift_closes_shift_id_unique\r\n  on public.shift_closes (shift_id, closed_at)\r\n  where shift_id is not null;\r\n\r\n-- Evita duplicar el mismo cierre si se reintenta sync\r\ncreate unique index if not exists idx_shift_closes_record_shift_closed\r\n  on public.shift_closes ((record_json->>'shiftId'), closed_at)\r\n  where record_json ? 'shiftId';\r\n\r\nselect public.crozzo_enable_pos_rls('shift_closes');\r\n\r\nnotify pgrst, 'reload schema';\r\n"}],
    getScript: function (key) {
      var s = this.scripts.find(function (x) { return x.key === key; });
      return s ? s.sql : '';
    },
    getRequiredKeys: function () {
      return this.scripts.filter(function (s) { return s.required; }).map(function (s) { return s.key; });
    },
    list: function () {
      return this.scripts.slice().sort(function (a, b) { return a.order - b.order; });
    }
  };
})(typeof window !== 'undefined' ? window : globalThis);
